// Real current HTTP/PG, read-only except two ordinary login sessions.
import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {loadCatalogTarget,executeCatalogSchema,readCatalogProtectedSnapshot} from '../../scripts/research-assets-catalog-schema.mjs';
import {assertFixtureTarget,withFixtureTransaction} from '../../../app/server/scripts/wp01/fixture-guard.mjs';
import {verifyAssetPublicBaseline} from '../../scripts/research-assets-public-baseline.mjs';
import {createAssetCatalogClient} from '../../src/research-assets-catalog-client.js';
import {assertAssetView,assertAssetPreviewExtras} from '../../src/research-assets-views.js';
assert.equal(process.argv[2],'--verify','EXPLICIT_C06_HTTP_READ_REQUIRED');const {env,ids}=loadCatalogTarget();assert.equal((await assertFixtureTarget(env)).databaseName,'wp01_test_full_baseline');assert.equal((await executeCatalogSchema()).action,'verified');
const read=fn=>withFixtureTransaction(env,'direct',fn,{readOnly:true}),before=await read(t=>readCatalogProtectedSnapshot(t,ids)),initial=await read(t=>t.auditLog.findFirst({where:{tenantId:ids.tenant,action:'research_assets_catalog_schema_20261112',target:'rh_asset'},select:{meta:true}}));assert.equal(before.oldAssetsHash,initial.meta.protectedSnapshot.oldAssetsHash);assert.equal(before.roleHash,initial.meta.protectedSnapshot.roleHash);
const publicProof=await read(t=>verifyAssetPublicBaseline(t,{tenantId:ids.tenant,expectedHash:initial.meta.protectedSnapshot.publicDefinitionHash}));
const registry=await read(t=>t.$queryRawUnsafe('SELECT * FROM rh_asset.asset_registry WHERE tenant_id=$1',ids.tenant)),events=await read(t=>t.$queryRawUnsafe('SELECT asset_id,event_type,actor_account_id,version_no,created_at,request_key FROM rh_asset.asset_event WHERE tenant_id=$1 ORDER BY asset_id,asset_revision',ids.tenant));assert.equal(registry.length,10);assert(registry.every(r=>r.deleted_at===null&&r.revision<=24));
const protocol=registry.find(r=>r.owner_account_id===ids.owner&&r.asset_kind==='protocol'),shared=registry.find(r=>r.owner_account_id===ids.admin&&r.asset_kind==='protocol');
const origin='http://127.0.0.1:19501',runtime=JSON.parse(readFileSync(new URL('../../../.tmp/researchhub-knowledge-local/runtime.json',import.meta.url),'utf8')),scope={studyGroupId:ids.group,researchProjectId:ids.project},checks=[];
for(const actor of ['owner','admin']){
 const login=await fetch(origin+'/api/auth/login',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json','X-ResearchHub-Request':'session-v1'},body:JSON.stringify({tenantSlug:ids.tenant,username:actor+'@example.org',password:runtime.password})});assert.equal(login.status,201);const cookie=login.headers.getSetCookie().map(x=>x.split(';')[0]).join(';'),user=await(await fetch(origin+'/api/auth/me',{headers:{Cookie:cookie}})).json();assert.equal(user.accountId,ids[actor]);
 const api=createAssetCatalogClient({user,scope,fetchImpl:(u,i)=>fetch(origin+u,{...i,headers:{...i.headers,Origin:origin,Cookie:cookie}})}),catalog=await api.get('/research-assets/catalog?pageSize=20'),context={scope,identityRevision:catalog.identityRevision};assert.equal(catalog.total,actor==='owner'?6:10);
 const graph=assertAssetView(await api.get('/research-assets/graph?pageSize=20'),'graph',context);assert.equal(graph.total,catalog.total);assert.equal(graph.nodes.filter(x=>x.kind==='asset').length,catalog.total);assert(graph.nodes.some(x=>x.kind==='knowledge'&&x.knowledgeTarget.docVersion===2));assert(graph.edges.some(x=>x.type==='citation'&&x.count===2));
 const contribution=assertAssetView(await api.get('/research-assets/contributions?pageSize=20'),'contributions',context);for(const type of ['created','revised','submitted','reviewed','cited'])assert.equal(contribution.totals[type],events.filter(e=>e.actor_account_id===ids[actor]&&e.event_type===type).length);
 const trend=assertAssetView(await api.get('/research-assets/usage'),'usage',context);assert.equal(trend.totals.cited,2);assert.equal(trend.totals.applied,0);assert.equal(trend.totals.downloaded,0);
 const trash=assertAssetView(await api.get('/research-assets/trash?pageSize=20'),'trash',context);assert.equal(trash.total,0);
 const all=[],cursors=[];let cursor=null;for(let n=0;n<4;n++){const path='/research-assets/recommendations?pageSize=20'+(cursor?'&cursor='+cursor:''),r=assertAssetView(await api.get(path),'recommendations',context);all.push(...r.items.map(x=>x.id));cursor=r.nextCursor;if(!cursor)break;assert(!cursors.includes(cursor));cursors.push(cursor);}assert.equal(new Set(all).size,all.length);assert.equal(all.length,catalog.total);assert.equal(cursor,null);
 const relation=await api.get('/research-assets/'+protocol.asset_id+'/preview?version=4&tab=relations');assertAssetPreviewExtras(relation,'relations',scope);assert(relation.relations.items.some(x=>x.kind==='knowledge'&&x.knowledgeTarget.docVersion===2));
 const cited=await api.get('/research-assets/'+shared.asset_id+'/preview?version=1&tab=citations');assertAssetPreviewExtras(cited,'citations',scope);assert.equal(cited.citations.total,2);
 const collaboration=await api.get('/research-assets/collaborations?collaborationView='+(actor==='owner'?'received':'sent'));assert.equal(collaboration.total,2);assert.equal(collaboration.counts.requested,actor==='owner'?2:0);
 // A real request deliberately bypasses only the client allowlist to exercise the HTTP boundary.
 const headers={Cookie:cookie,'X-Study-Group-Id':ids.group,'X-Research-Project-Id':ids.project,'X-ResearchHub-Actor':user.accountId,'X-ResearchHub-Auth-Version':String(user.authVersion)};
 for(const path of ['/graph?includePrivate=true','/recommendations?assetId=x','/trash?page=1&page=2']){const r=await fetch(origin+'/api/research-assets'+path,{headers});assert.equal(r.status,400);}
 const wrong=await fetch(origin+'/api/research-assets/graph',{headers:{...headers,'X-Research-Project-Id':'not-authorized-project'}});assert([403,404].includes(wrong.status));
 checks.push({actor,visible:catalog.total,graphNodes:graph.nodes.length,graphEdges:graph.edges.length,contributions:contribution.totals,recommendedWithoutDuplicates:all.length,trend:trend.totals,trash:trash.total,collaborationRows:collaboration.total,realInvalidQueryAndScopeRefused:true});
}
const anonymous=await fetch(origin+'/api/research-assets/graph');assert([401,403].includes(anonymous.status));
assert.deepEqual(await read(t=>readCatalogProtectedSnapshot(t,ids)),before);assert.equal((await read(t=>t.$queryRawUnsafe('SELECT count(*)::int n FROM rh_asset.asset_event WHERE tenant_id=$1',ids.tenant)))[0].n,events.length);
const afterProof=await read(t=>verifyAssetPublicBaseline(t,{tenantId:ids.tenant,expectedHash:initial.meta.protectedSnapshot.publicDefinitionHash}));assert.equal(afterProof.fullDefinitionHash,publicProof.fullDefinitionHash);
console.log(JSON.stringify({syntheticOnly:true,realHttp:true,runtimePid:runtime.pid,checks,assets:10,versions:(await read(t=>t.$queryRawUnsafe('SELECT count(*)::int n FROM rh_asset.version_policy WHERE tenant_id=$1',ids.tenant)))[0].n,events:events.length,recycleEvents:events.filter(e=>['trashed','restored'].includes(e.event_type)).length,oldAssetsRolesPublicUnchanged:true,publicFullHash:publicProof.fullDefinitionHash,businessWrites:0,modelCalls:0},null,2));
